      "interpretation": "Fechamento abaixo das médias móveis — novo fundo intra-período; sinal baixista."
    },
    {
      "indicator": "MM20",
      "reading": "33.2920",
      "interpretation": "Preço abaixo da MM20 → tendência de curto prazo negativa."
    },
    {
      "indicator": "MM50",
      "reading": "33.9826",
      "interpretation": "Preço abaixo da MM50 → tendência de médio prazo negativa."
    },
    {
      "indicator": "MM200",
      "reading": "33.1936",
      "interpretation": "Preço abaixo da MM200 → tendência de longo prazo pressionada; MM20 levemente acima da MM200."
    },
    {
      "indicator": "EMA9",
      "reading": "32.8849",
      "interpretation": "EMA9 abaixo da EMA21 → pressão vendedora de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "33.2747",
      "interpretation": "Referência de curto-médio prazo; preço e EMA9 abaixo dela."
    },
    {
      "indicator": "MACD",
      "reading": "-0.3790",
      "interpretation": "MACD negativo e abaixo da linha de sinal → momentum vendedor."
    },
    {
      "indicator": "MACD_signal",
      "reading": "-0.2808",
      "interpretation": "Linha de sinal acima do MACD confirma tendência de baixa enquanto não for cruzada."
    },
    {
      "indicator": "MACD_hist",
      "reading": "-0.0982",
      "interpretation": "Histograma negativo — pressão vendedora presente e recente ampliação da baixa."
    },
    {
      "indicator": "RSI14",
